from pathlib import Path
import json,hashlib,base64
R=Path(__file__).parent;V5=R;proj=json.loads((V5/'projection.json').read_text());name='Thoracic duct — left venous angle';paths={};binding={}
for view,y,h in [('overview',205,810),('detail',1180,630)]:
 obj=proj['views'][view]['objects'][name];v=obj['vertices'];assert len(v)==40 and len(obj['triangles'])==76
 centers=[[sum(v[i+j][k] for j in range(8))/8 for k in range(2)] for i in range(0,40,8)]
 old=proj['views'][view]['camera']['anchors']
 for idx,key in [(0,'lower'),(-1,'upper')]:assert max(abs(centers[idx][0]-old[key][0]),abs(centers[idx][1]-(1-old[key][1])))<1e-6
 points=[[800+x*648,y+z*h] for x,z in centers];paths[view]='M '+' L '.join(f'{x:.6f} {y:.6f}' for x,y in points);binding[view]={'ring_centers_normalized':centers,'panel_points':points,'lower_to_upper_cap':True,'triangles':76,'rings':5,'ring_vertices':8}
imgs={lang:base64.b64encode((V5/f'comparison-{lang}.png').read_bytes()).decode() for lang in ['en','zh']};hashes={lang:hashlib.sha256((V5/f'comparison-{lang}.png').read_bytes()).hexdigest() for lang in imgs}
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Source routes · accepted v5 context</title><style>
:root{color-scheme:dark;font-family:Arial,'Noto Sans CJK SC',sans-serif;background:#11171c;color:#e9edf0}*{box-sizing:border-box}body{max-width:1520px;margin:auto;padding:20px}header{display:flex;justify-content:space-between;gap:16px;align-items:start}h1{font-size:26px;margin:0 0 10px}p{line-height:1.45;color:#b8c7d1}.controls{display:flex;gap:8px;flex-wrap:wrap}button{font:inherit;background:#233441;color:#e9edf0;border:1px solid #738f9f;border-radius:8px;padding:10px 14px;cursor:pointer}button:focus-visible{outline:3px solid #a2e3ff;outline-offset:3px}button:disabled{opacity:.65;cursor:default}svg{display:block;width:100%;height:auto}.flow{stroke:#9df6d5;stroke-width:2.4;stroke-dasharray:5 19;fill:none;animation:direction 3.2s linear infinite;pointer-events:none;opacity:.82}.paused .flow{animation-play-state:paused;opacity:0}@keyframes direction{to{stroke-dashoffset:-24}}@media(prefers-reduced-motion:reduce){.flow{animation:none!important;opacity:0!important}}@media(max-width:700px){header{display:block}.controls{margin:12px 0}body{padding:10px}h1{font-size:22px}}
</style><body class="paused"><header><div><h1 data-en="Original routes · revised body context" data-zh="保留原始路径 · 调整身体参照"></h1><p data-en="Accepted static v5 contour and all 7 source routes retained. Motion highlights the selected thoracic route only." data-zh="保留已认可的v5静态轮廓和全部7条源路径；仅对所选胸导管路径添加流向提示。"></p></div><div class="controls"><button id="lang" type="button">中文</button><button id="motion" type="button"></button></div></header><p id="state" role="status"></p><p data-en="Teaching direction: lower model cap → upper model cap. No claim of measured flow, a continuous lumen or a verified vein connection; the other 6 routes stay static." data-zh="教学方向：下端模型封口 → 上端模型封口。不代表实测流动、连续管腔或已验证静脉连接；其余6条路径保持静态。"></p>
<svg viewBox="0 0 1520 1960" role="img" aria-labelledby="diagramTitle diagramDesc"><title id="diagramTitle"></title><desc id="diagramDesc"></desc><image id="plate" width="1520" height="1960" href="data:image/png;base64,EN_IMAGE"/><path class="flow" id="overview-flow" d="OVERVIEW_PATH"/><path class="flow" id="detail-flow" d="DETAIL_PATH"/></svg><footer><p data-en="Reference pattern: thoracic duct → left venous angle for most body regions; right head/neck, right chest and right upper limb are the exception. This does not validate the model caps." data-zh="参考模式：身体大部分区域经胸导管回流至左静脉角；右侧头颈、右侧胸部及右上肢为例外。这不验证模型封口。"></p><p data-en="Direction reference: OpenStax Anatomy and Physiology2e §21.1. Source-named model endpoints are not anatomical outlet validation. Animation is illustrative; its browser rendering has not been verified in this environment." data-zh="方向参考：OpenStax Anatomy and Physiology2e §21.1。源模型端点名称不等于解剖出口验证。动画仅作示意；本环境尚未验证其实际浏览器呈现。"></p><a href="https://openstax.org/books/anatomy-and-physiology-2e/pages/21-1-anatomy-of-the-lymphatic-and-immune-systems">OpenStax §21.1</a></footer><script>
const images=IMAGES_JSON;const reduced=matchMedia('(prefers-reduced-motion: reduce)');let lang='en',paused=true;try{lang=localStorage.getItem('lymph152-v5-lang')||'en';paused=localStorage.getItem('lymph152-v5-paused')!=='false'}catch{}if(!['en','zh'].includes(lang))lang='en';if(reduced.matches)paused=true;
const labels={en:{motion:()=>paused?'Show direction':'Pause direction',state:()=>reduced.matches?'Reduced motion: original static plate.':paused?'Paused: original static plate.':'Selected route only: lower → upper; not physiological timing.',title:'Original and Updated source routes with refined body context',desc:'Same seven source routes and cap locations in matched overview and oblique detail; only the selected thoracic route receives an optional moving highlight.'},zh:{motion:()=>paused?'显示方向':'暂停方向',state:()=>reduced.matches?'减少动态效果：显示原始静态图。':paused?'已暂停：显示原始静态图。':'仅提示所选路径：下端→上端；不代表生理时间。',title:'原始路径与调整身体参照后的对比',desc:'匹配总览和斜向近景中的7条源路径及封口位置不变；仅对所选胸导管路径添加可选移动高亮。'}};
function render(){document.documentElement.lang=lang;document.querySelectorAll('[data-en]').forEach(e=>e.textContent=e.dataset[lang]);document.getElementById('lang').textContent=lang==='en'?'中文':'EN';document.body.classList.toggle('paused',paused||reduced.matches);const b=document.getElementById('motion');b.textContent=labels[lang].motion();b.disabled=reduced.matches;b.setAttribute('aria-pressed',String(!paused));document.getElementById('state').textContent=labels[lang].state();document.getElementById('diagramTitle').textContent=labels[lang].title;document.getElementById('diagramDesc').textContent=labels[lang].desc;document.getElementById('plate').setAttribute('href','data:image/png;base64,'+images[lang])}
document.getElementById('lang').onclick=()=>{lang=lang==='en'?'zh':'en';try{localStorage.setItem('lymph152-v5-lang',lang)}catch{}render()};document.getElementById('motion').onclick=()=>{paused=!paused;try{localStorage.setItem('lymph152-v5-paused',String(paused))}catch{}render()};reduced.addEventListener('change',()=>{if(reduced.matches)paused=true;render()});render();
</script></body></html>'''
caps=[v['panel_points'][i] for v in binding.values() for i in [0,-1]]
mask='<defs><mask id="cap-safe"><rect width="1520" height="1960" fill="white"/>'+''.join(f'<circle cx="{x:.6f}" cy="{y:.6f}" r="9" fill="black"/>' for x,y in caps)+'</mask></defs>'
html=html.replace('<image id="plate"',mask+'<image id="plate"').replace('<path class="flow"','<path mask="url(#cap-safe)" class="flow"')
html=html.replace('EN_IMAGE',imgs['en']).replace('IMAGES_JSON',json.dumps(imgs)).replace('OVERVIEW_PATH',paths['overview']).replace('DETAIL_PATH',paths['detail']);(R/'index.html').write_text(html)
(R/'projection-binding.json').write_text(json.dumps({'input_plate_sha256':hashes,'source_scene_sha256':proj['source_sha256'],'selected_source_name':name,'source_object_count':7,'total_triangles':372,'selected_projection':binding,'semantics':'Illustrative lower-to-upper direction only; cap is model limit, not verified venous junction or lumen. Other six paths static.'},indent=2))
